        array("id" => "s2021e2", "season" => 2021, "number" => 2, "name" => "Ao", "airdate" => "17 Jan 2021", "runtime" => 30, "rating" => 7, "summary" => "Team 7 is given a mission to escort Katasuke and the prosthetic arm to a research lab in another city. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1375801.jpg"),
