        array("id" => "s2021e7", "season" => 2021, "number" => 7, "name" => "Karma", "airdate" => "21 Feb 2021", "runtime" => 30, "rating" => 9, "summary" => "After Ao's defeat, Koji Kashin appears before Team 7 and attempts to ensnare them in a sealing jutsu and eliminate them. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1375824.jpg"),
        array("id" => "s2021e8", "season" => 2021, "number" => 8, "name" => "The Awakening", "airdate" => "28 Feb 2021", "runtime" => 30, "rating" => 9, "summary" => "Koji Kashin retreats from battle after seeing that Boruto has a \"Karma\" mark on his hand. Shortly after, Team 7 discovers a battle site where a boy lies unconscious.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1375838.jpg"),
        array("id" => "s2021e9", "season" => 2021, "number" => 9, "name" => "Resonance", "airdate" => "7 Mar 2021", "runtime" => 30, "rating" => 9, "summary" => "Boruto and the others learn that the boy named Kawaki is the target that Kara has been seeking. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1375941.jpg"),
        array("id" => "s2021e10", "season" => 2021, "number" => 10, "name" => "Escape", "airdate" => "14 Mar 2021", "runtime" => 30, "rating" => 9.5, "summary" => "Boruto and the others return to the technology lab to contain and watch over Kawaki while Konohamaru returns to the Leaf Village to report the events of the mission to Naruto.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376400.jpg"),
        array("id" => "s2021e11", "season" => 2021, "number" => 11, "name" => "A Stray Dog", "airdate" => "21 Mar 2021", "runtime" => 30, "rating" => 9, "summary" => "Wounded and hungry, Kawaki escapes from the tech lab and makes his way to a nearby town to find food. Sumire tracks him down, believing she can help him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376584.jpg"),
        array("id" => "s2021e12", "season" => 2021, "number" => 12, "name" => "The Past", "airdate" => "28 Mar 2021", "runtime" => 30, "rating" => 9, "summary" => "Kawaki falls unconscious and is taken to the Leaf Village. While he sleeps in a hospital, he is plagued with nightmares of his childhood days when he lived with his abusive father.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376698.jpg"),
        array("id" => "s2021e13", "season" => 2021, "number" => 13, "name" => "Coexistence", "airdate" => "4 Apr 2021", "runtime" => 30, "rating" => 9.3, "summary" => "During a Kage Summit, it is decided that Naruto will take custody of Kawaki. Kawaki reluctantly accompanies Naruto to the Uzumaki household.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376829.jpg"),
        array("id" => "s2021e14", "season" => 2021, "number" => 14, "name" => "The Uzumaki Household", "airdate" => "11 Apr 2021", "runtime" => 30, "rating" => 7.5, "summary" => "Kawaki starts living at the Uzumaki household. At first, he has a difficult time opening up and trusting the family, but the peaceful environment of the house helps to calm him down. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376835.jpg"),
        array("id" => "s2021e15", "season" => 2021, "number" => 15, "name" => "A Vase", "airdate" => "18 Apr 2021", "runtime" => 30, "rating" => 9.3, "summary" => "Kawaki offers to work with Boruto to learn more about the Karma they both possess, but Boruto is still angry with him for breaking Himawari's vase. To try to make amends, Kawaki goes into town with Naruto to find a new vase.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376842.jpg"),
        array("id" => "s2021e16", "season" => 2021, "number" => 16, "name" => "A Binding Force", "airdate" => "25 Apr 2021", "runtime" => 30, "rating" => 9.3, "summary" => "Naruto trains Boruto at shinobi hand-to-hand combat while Kawaki and others watch. Kawaki insists that Boruto uses his Karma against Naruto to learn how to wield it's power.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376865.jpg"),
        array("id" => "s2021e17", "season" => 2021, "number" => 17, "name" => "Delta", "airdate" => "2 May 2021", "runtime" => 30, "rating" => 9.6, "summary" => "Delta loses patience with Koji Kashin and begins to search for Kawaki herself. Meanwhile, to learn more about how to control their Karma, Boruto and Kawaki spar with each other while Naruto and Himawari watch.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376877.jpg"),
        array("id" => "s2021e18", "season" => 2021, "number" => 18, "name" => "Monsters", "airdate" => "9 May 2021", "runtime" => 30, "rating" => 9.8, "summary" => "Delta makes her way into the village and appears before Naruto and the others to take Kawaki back. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376888.jpg"),
        array("id" => "s2021e19", "season" => 2021, "number" => 19, "name" => "Overload", "airdate" => "16 May 2021", "runtime" => 30, "rating" => 9.3, "summary" => "Naruto continues his battle against Delta, but she has scientific ninja tools implanted in her body that can shoot destructive beams and absorb any jutsu. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1376897.jpg"),
        array("id" => "s2021e20", "season" => 2021, "number" => 20, "name" => "Apprentice", "airdate" => "23 May 2021", "runtime" => 30, "rating" => 9.3, "summary" => "After losing his arm in battle, Kawaki is given a prosthetic arm powered by Naruto's chakra. Learning about the powers and capabilities of using chakra, Kawaki asks Naruto to be trained in ninjutsu.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1377173.jpg"),
