        array("id" => "s2021e23", "season" => 2021, "number" => 23, "name" => "Surprise Attack...!!", "airdate" => "13 Jun 2021", "runtime" => 30, "rating" => 9.4, "summary" => "Everyone is going about their daily lives in the village until Jigen suddenly appears before Kawaki.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/550/1377215.jpg"),
