        array("id" => "s2021e25", "season" => 2021, "number" => 25, "name" => "Proof", "airdate" => "27 Jun 2021", "runtime" => 30, "rating" => 9.4, "summary" => "Boruto, Kawaki and the others sense something has happened to Naruto. But before anyone can act, Shikamaru and his subordinates arrive and erect a barrier around the Uzumaki home to contain Kawaki, believing he can't be trusted.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377620.jpg"),
        array("id" => "s2021e26", "season" => 2021, "number" => 26, "name" => "The New Team Seven", "airdate" => "4 Jul 2021", "runtime" => 30, "rating" => 9.2, "summary" => "Boruto, Sarada, Mitsuki, and Kawaki arrive at the dimension that Naruto is trapped in, but Boro is there waiting for them. The four create a team with Sarada leading them to fight Boro, who uses a black mist to paralyze his enemies.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377630.jpg"),
