        array("id" => "s2021e29", "season" => 2021, "number" => 29, "name" => "The Outcast", "airdate" => "1 Aug 2021", "runtime" => 30, "rating" => 9, "summary" => "Kawaki begins to worry that his presence is endangering everyone in the Leaf Village. Just as he makes the decision to leave, he notices Himawari acting strange.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377678.jpg"),
        array("id" => "s2021e30", "season" => 2021, "number" => 30, "name" => "Clues to Kara", "airdate" => "8 Aug 2021", "runtime" => 30, "rating" => 8.8, "summary" => "Konohamaru and Sai are given a mission to infiltrate Boro's cult in order to obtain information on Kara and its whereabouts.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377694.jpg"),
        array("id" => "s2021e31", "season" => 2021, "number" => 31, "name" => "The Chase", "airdate" => "15 Aug 2021", "runtime" => 30, "rating" => 8.7, "summary" => "News has spread throughout the Leaf Village that a cloaked man has stolen data from the archives. Team 10 decides to launch their own investigation to find and catch the thief.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377898.jpg"),
        array("id" => "s2021e32", "season" => 2021, "number" => 32, "name" => "Amado's Defection", "airdate" => "22 Aug 2021", "runtime" => 30, "rating" => 9.3, "summary" => "Amado defects from Kara. Desiring to seek asylum in the Leaf Village, he takes Shikadai hostage.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377952.jpg"),
        array("id" => "s2021e33", "season" => 2021, "number" => 33, "name" => "True Identity", "airdate" => "29 Aug 2021", "runtime" => 30, "rating" => 9.7, "summary" => "Amado reveals to Naruto and the others the knowledge that he possesses regarding Jigen, the Otsutsuki Clan, and Karma.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377968.jpg"),
