        array("id" => "s2021e35", "season" => 2021, "number" => 35, "name" => "Prepared", "airdate" => "12 Sep 2021", "runtime" => 30, "rating" => 9.8, "summary" => "Isshiki regains his true form and goes to the Leaf Village to recapture Kawaki. The Leaf shinobi prepare for his arrival.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1377995.jpg"),
        array("id" => "s2021e36", "season" => 2021, "number" => 36, "name" => "Sacrifice", "airdate" => "19 Sep 2021", "runtime" => 30, "rating" => 10, "summary" => "Boruto opens a portal and transports Isshiki and himself to another dimension. Naruto and Sasuke follow them, and the final battle against Isshiki begins.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1378000.jpg"),
