        array("id" => "s2021e42", "season" => 2021, "number" => 42, "name" => "The Night Before The Final Round", "airdate" => "31 Oct 2021", "runtime" => 30, "rating" => 8.3, "summary" => "The Leaf genin that passed the first two rounds are given one day to rest and train before the final round of the Chunin Exam.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1378830.jpg"),
        array("id" => "s2021e43", "season" => 2021, "number" => 43, "name" => "Inojin vs. Houki", "airdate" => "7 Nov 2021", "runtime" => 30, "rating" => 8.7, "summary" => "The final round of the Chunin Exam begins and Inojin and Houki are selected to fight in the first match. Meanwhile, when Boruto and Mitsuki are heading to the arena for the Exam, they spot suspicious men in the village.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1378869.jpg"),
        array("id" => "s2021e44", "season" => 2021, "number" => 44, "name" => "The Legend of the Monster Cat", "airdate" => "14 Nov 2021", "runtime" => 30, "rating" => 8.3, "summary" => "The next match of the final round is Wasabi versus Iwabe. Iwabe is pumped to take her on, but Wasabi is not as enthusiastic.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/551/1379418.jpg"),
        array("id" => "s2021e45", "season" => 2021, "number" => 45, "name" => "Showdown Between Best Friends", "airdate" => "21 Nov 2021", "runtime" => 30, "rating" => 9, "summary" => "Sarada and Cho-Cho are chosen for the third match of the final round of the Chunin Exam. Even though they're best friends, the two make a promise to each other to give it everything that they've got and take the fight seriously.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/552/1380203.jpg"),
        array("id" => "s2021e46", "season" => 2021, "number" => 46, "name" => "Samurai vs. Science", "airdate" => "28 Nov 2021", "runtime" => 30, "rating" => 9, "summary" => "Boruto and Mitsuki are called for the next match. Unfortunately, due to them not arriving on time for the Exam, they are disqualified, which leads to the final match between Denki and Tsubaki.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/552/1380382.jpg"),
        array("id" => "s2021e47", "season" => 2021, "number" => 47, "name" => "Team 7's Last Mission?!", "airdate" => "5 Dec 2021", "runtime" => 30, "rating" => 8.3, "summary" => "As a chunin, Sarada will become Team 7's new captain, relieving Konohamaru of his duties. The team becomes saddened by this fact, but when a mission Konohamaru is on goes awry, they ask to have one final mission with him as their leader.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/380/952338.jpg"),
        array("id" => "s2021e48", "season" => 2021, "number" => 48, "name" => "Kawaki, the Path to Shinobi", "airdate" => "12 Dec 2021", "runtime" => 30, "rating" => 8.3, "summary" => "For Kawaki to become a genin, Naruto has him go on D-Rank missions, which will serve as tests to see if he is qualified. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/382/957305.jpg"),
        array("id" => "s2021e49", "season" => 2021, "number" => 49, "name" => "Order Violation", "airdate" => "19 Dec 2021", "runtime" => 30, "rating" => 8.3, "summary" => "Given one last chance at becoming a genin, Kawaki is assigned to join Shikadai and Cho-Cho on a mission to escort and protect Mozuku from the Land of Calm Seas.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/384/962423.jpg"),
        array("id" => "s2021e50", "season" => 2021, "number" => 50, "name" => "A Wish", "airdate" => "26 Dec 2021", "runtime" => 30, "rating" => 8.3, "summary" => "Kawaki, Shikadai and Cho-Cho are attacked by shinobi that steal Mozuku's package. Realizing the mission is not a regular escort mission, Shikadai makes the decision to return home, but Kawaki disregards his orders and goes after the enemy.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/386/965143.jpg"),
    )),
    array("number" => 2022, "name" => "#231 - #281", "rating" => 5.7, "episodes" => array(
        array("id" => "s2022e1", "season" => 2022, "number" => 1, "name" => "The Rusty Sword", "airdate" => "9 Jan 2022", "runtime" => 30, "rating" => 8.7, "summary" => "When traveling merchants are attacked by bandits, Team 15 is sent out to investigate the incidents. When she finds a clue at a crime scene, Tsubaki suspects that a samurai, whom she trained with long ago, is involved in the robberies.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/552/1382426.jpg"),
        array("id" => "s2022e2", "season" => 2022, "number" => 2, "name" => "Captain Denki's First Mission", "airdate" => "16 Jan 2022", "runtime" => 30, "rating" => 5, "summary" => "Denki is informed of a new mission for Team 5 by Shikamaru and Naruto, a B-rank mission to deliver autonomous puppets to the Land of Water.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/553/1384105.jpg"),
        array("id" => "s2022e3", "season" => 2022, "number" => 3, "name" => "The New Team 7 Jumps Into Action", "airdate" => "23 Jan 2022", "runtime" => 30, "rating" => 6.8, "summary" => "Team 7, with Kawaki as its newest member, is assigned a mission to escort Katasuke to the Hidden Mist Village for a ceremony. Boruto uses the mission as an opportunity to visit Kagura, who is now the warden of a prison.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/554/1385381.jpg"),
        array("id" => "s2022e4", "season" => 2022, "number" => 4, "name" => "The Unleashed Villain", "airdate" => "30 Jan 2022", "runtime" => 30, "rating" => 6.5, "summary" => "Pirates infiltrate the prison to break out their clan leader.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/555/1387824.jpg"),
        array("id" => "s2022e5", "season" => 2022, "number" => 5, "name" => "Infiltrating Dotou Island", "airdate" => "6 Feb 2022", "runtime" => 30, "rating" => 4.6, "summary" => "Team 7 and Kagura head over to Dotou Island to rescue Team 5 and the mining workers.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/557/1393179.jpg"),
        array("id" => "s2022e6", "season" => 2022, "number" => 6, "name" => "Cut and Run", "airdate" => "13 Feb 2022", "runtime" => 30, "rating" => 7.7, "summary" => "Kagura sends Boruto, Kawaki, and Buntan to investigate an enormous mobile fortress belonging to the Funato. Meanwhile, Sarada, Mitsuki and Team 5 to try to rescue the people of Dotou Island.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/559/1397523.jpg"),
        array("id" => "s2022e7", "season" => 2022, "number" => 7, "name" => "The Mobile Fortress", "airdate" => "20 Feb 2022", "runtime" => 30, "rating" => 5.5, "summary" => "Boruto, Kawaki, and Buntan find a powerful weapon aboard the mobile fortress. Kagura, Hebiichigo, and Kyoho join them to help destroy the weapon, but Tenma of the Funato clan stands in their way. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/396/992172.jpg"),
        array("id" => "s2022e8", "season" => 2022, "number" => 8, "name" => "A Killer on the Ship", "airdate" => "27 Feb 2022", "runtime" => 30, "rating" => 7.3, "summary" => "Someone is murdered aboard the ship heading back to the Mist Village. Kyoho is considered to be the prime suspect, but he claims to be innocent. Boruto and Iwabe stand guard over Kyoho while everyone else searches the ship for clues.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/563/1409843.jpg"),
        array("id" => "s2022e9", "season" => 2022, "number" => 9, "name" => "The Boy from the Isle of Shipbuilders", "airdate" => "6 Mar 2022", "runtime" => 30, "rating" => 6.3, "summary" => "Boruto and the others are stranded in the middle of the ocean due to the ship being damaged. Luckly, they are found by the shipbuilders, Kajiki and Ikada, who are willing to tow the ship to their island to help repair it. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/564/1411469.jpg"),
        array("id" => "s2022e10", "season" => 2022, "number" => 10, "name" => "Ikada's Dream", "airdate" => "13 Mar 2022", "runtime" => 30, "rating" => 5.3, "summary" => "Boruto travels with Ikada in his boat to get a ship part from the parts factory. Boruto learns about Ikada's dream of becoming a great shipbuilder. As the two continued to get acquainted, they find themselves in the middle of a storm. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/565/1414498.jpg"),
        array("id" => "s2022e11", "season" => 2022, "number" => 11, "name" => "Ikada's Secret", "airdate" => "20 Mar 2022", "runtime" => 30, "rating" => 7.3, "summary" => "Ikada's older sister, Seiren, goes to the shipbuilding island to bring her little brother back to the Funato clan. However, Ikada refuses because he wants to learn much more about shipbuilding.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/566/1417034.jpg"),
        array("id" => "s2022e12", "season" => 2022, "number" => 12, "name" => "Seiren", "airdate" => "27 Mar 2022", "runtime" => 30, "rating" => 8, "summary" => "Seiren and the followers of the Funatos start their attack on the shipbuilding island. Seiren directly targets Boruto, who has nothing to oppose her fighting technique.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1424030.jpg"),
        array("id" => "s2022e13", "season" => 2022, "number" => 13, "name" => "Where I Belong", "airdate" => "3 Apr 2022", "runtime" => 30, "rating" => 7.3, "summary" => "Boruto and his comrades enjoy a little time off and decide to help Kirigakure fight the Funatos. They then take a detour to Kagura's home village.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/570/1425165.jpg"),
        array("id" => "s2022e14", "season" => 2022, "number" => 14, "name" => "Rift", "airdate" => "10 Apr 2022", "runtime" => 30, "rating" => 7.3, "summary" => "Boruto and his comrades prepare everything for the defense of the village. After Funamushi finds out that the bridges have been destroyed, he sends a scouting party to check out the situation.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/570/1427024.jpg"),
        array("id" => "s2022e15", "season" => 2022, "number" => 15, "name" => "Funamushi's Tenacity", "airdate" => "17 Apr 2022", "runtime" => 30, "rating" => 8, "summary" => "Hebiichigo has fled after the curse mark was released from her. Buntan and Kyoho want to get her back so they can fight Funamushi and his soldiers together with Kagura, Boruto and the others.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/570/1427035.jpg"),
        array("id" => "s2022e16", "season" => 2022, "number" => 16, "name" => "A Heavy Loss", "airdate" => "24 Apr 2022", "runtime" => 30, "rating" => 7.4, "summary" => "To take revenge for Seiren, Funamushi stabs Kagura in the back with his sword. Boruto and his friends do everything possible to save their comrade.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/570/1427284.jpg"),
        array("id" => "s2022e17", "season" => 2022, "number" => 17, "name" => "For Kagura", "airdate" => "1 May 2022", "runtime" => 30, "rating" => 6, "summary" => "To fulfill Kagura's last wish, Boruto and his friends decide to defend his home village. However, during the last attack of Funamushi's people, the supply storage was destroyed and the village is facing a food crisis. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/571/1428514.jpg"),
        array("id" => "s2022e18", "season" => 2022, "number" => 18, "name" => "Another Fierce Battle", "airdate" => "8 May 2022", "runtime" => 30, "rating" => 6.8, "summary" => "Funamushi and his unit launch another attack on Kagura's village. He finally wants to take revenge for Seiren and hunt down Boruto. However, he and his unit are already expected. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/573/1432875.jpg"),
        array("id" => "s2022e19", "season" => 2022, "number" => 19, "name" => "Burgeoning Hatred", "airdate" => "15 May 2022", "runtime" => 30, "rating" => 6.3, "summary" => "The fight against Funamushi is over and Kagura has been avenged. However, Boruto and his people are not satisfied with that. They want to continue fighting in the war against the Funatos. In the meantime, they are still looking for Denki and Iwabee.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/573/1432881.jpg"),
        array("id" => "s2022e20", "season" => 2022, "number" => 20, "name" => "The Blood of the Funato", "airdate" => "22 May 2022", "runtime" => 30, "rating" => 6.4, "summary" => "The clock is turned back a bit and the events in the ranks of the Funatos are shown. Ikada is still hoping that Seiren will come around and join the fight. Meanwhile, Araumi is furious that Ikada won't join the fight. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/575/1438074.jpg"),
        array("id" => "s2022e21", "season" => 2022, "number" => 21, "name" => "Their Resolve", "airdate" => "29 May 2022", "runtime" => 30, "rating" => 6, "summary" => "Boruto has learned that Ikada is leading the Funatos into battle. He blames himself for putting Ikada on that path. Meanwhile, Isari tries to negotiate a peace treaty with Chojuro", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/575/1439589.jpg"),
        array("id" => "s2022e22", "season" => 2022, "number" => 22, "name" => "The Desire to Believe", "airdate" => "5 Jun 2022", "runtime" => 30, "rating" => 6.3, "summary" => "Boruto, Sarada and Mitsuki want to get to Master Mizukage to convince him to end the war. But to do that, they first need a ship. On the shipbuilding island they try to borrow one.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/575/1439605.jpg"),
        array("id" => "s2022e23", "season" => 2022, "number" => 23, "name" => "Conflicting Feelings", "airdate" => "12 Jun 2022", "runtime" => 30, "rating" => 6.5, "summary" => "Boruto, Sarada and Mitsuki confront Ikada to convince him to finally end the war with Kirigakure. However, the hatred is firmly rooted in Ikada.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/575/1439888.jpg"),
        array("id" => "s2022e24", "season" => 2022, "number" => 24, "name" => "The Spiral of Revenge", "airdate" => "19 Jun 2022", "runtime" => 30, "rating" => 7.2, "summary" => "Boruto offers Ikada his life to stop the war. Will Ikada accept or ultimately stick to his revenge? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/575/1439891.jpg"),
        array("id" => "s2022e25", "season" => 2022, "number" => 25, "name" => "A Tricky Assignment", "airdate" => "26 Jun 2022", "runtime" => 30, "rating" => 6.3, "summary" => "Boruto and his comrades have returned to Konohagakure. There, they are commended by the Seventh Hokage for their outstanding deeds in the Water Kingdom. However, Boruto is worried about Ikada, as he does not know what fate awaits him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/575/1439894.jpg"),
        array("id" => "s2022e26", "season" => 2022, "number" => 26, "name" => "The Ultimate Recipe", "airdate" => "3 Jul 2022", "runtime" => 30, "rating" => 3.6, "summary" => "Chocho and Inojin are worried that they are just a burden to Shikadai. Just at that moment, the two are given a mission that they must complete without Shikadai. It's about catching a renegade ninja.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/576/1441799.jpg"),
        array("id" => "s2022e27", "season" => 2022, "number" => 27, "name" => "Konohamaru Becomes the Hokage?!", "airdate" => "10 Jul 2022", "runtime" => 30, "rating" => 6, "summary" => "Naruto has received an order and is supposed to play in his role as Hokage in the new Kagemasa movie. However, he has promised Himawari and his family that he will go on a trip with them. When Konohamaru hears about this, he offers Naruto to take over his rol…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/576/1442013.jpg"),
        array("id" => "s2022e28", "season" => 2022, "number" => 28, "name" => "The Uzumaki Family's Hot Springs Vacation", "airdate" => "17 Jul 2022", "runtime" => 30, "rating" => 5.8, "summary" => "Himawari wins a trip to a hostel near the hot springs and travels there with her whole family. However, the Uzumakis do not know that the hostel is haunted.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/577/1443507.jpg"),
        array("id" => "s2022e29", "season" => 2022, "number" => 29, "name" => "Unhealing Wounds", "airdate" => "24 Jul 2022", "runtime" => 30, "rating" => 5.2, "summary" => "A criminal is causing fear and terror in Konoha. He is hunting down former shinobi who have mastered the Wind Hideout. Mitsuki and Mikazuki are close to solving the case. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/577/1443762.jpg"),
        array("id" => "s2022e30", "season" => 2022, "number" => 30, "name" => "Fireworks of Love", "airdate" => "31 Jul 2022", "runtime" => 30, "rating" => 4.8, "summary" => "Boruto and Kakashi watch as two old men argue. Kakashi wants to stay out of it, but Boruto tries to settle the dispute. He finds out that their argument is about the organization of the fireworks display. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/578/1445689.jpg"),
        array("id" => "s2022e31", "season" => 2022, "number" => 31, "name" => "Kawaki Enters the Ninja Academy", "airdate" => "7 Aug 2022", "runtime" => 30, "rating" => 3.8, "summary" => "Kawaki is given a top secret mission by Naruto. He is to protect a princess who is visiting the ninja academy as an exchange student. For this reason, Kawaki joins the academy and begins his covert mission.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/578/1446954.jpg"),
        array("id" => "s2022e32", "season" => 2022, "number" => 32, "name" => "The Princess's Tea Party", "airdate" => "14 Aug 2022", "runtime" => 30, "rating" => 3.4, "summary" => "Kae wants to host a tea party with her classmates and get to know them better. Kawaki is also invited, to everyone's amazement. There he can continue his mission as a bodyguard. The next fiasco is also not long in coming. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/578/1447215.jpg"),
        array("id" => "s2022e33", "season" => 2022, "number" => 33, "name" => "Bloom, Hana! The Teacher's Gifts", "airdate" => "21 Aug 2022", "runtime" => 30, "rating" => 4, "summary" => "Special teachers come to the academy to show the children various ninjutsu. When it is revealed who these teachers are, Kawaki in particular is surprised. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/579/1447837.jpg"),
        array("id" => "s2022e34", "season" => 2022, "number" => 34, "name" => "The Seven Mysteries Investigative Team Forms!", "airdate" => "28 Aug 2022", "runtime" => 30, "rating" => 4, "summary" => "In Himawari's class, there is a rumor about the \"Seven Mysteries\" at the Academy. They form an expeditionary force to uncover the mystery.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/579/1448582.jpg"),
        array("id" => "s2022e35", "season" => 2022, "number" => 35, "name" => "Team Rivalry: Practical Skills Training!", "airdate" => "4 Sep 2022", "runtime" => 30, "rating" => 4, "summary" => "Kawaki and Himawari participate in a training session in the forest near the academy. However, not everything goes smoothly.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/579/1448829.jpg"),
        array("id" => "s2022e36", "season" => 2022, "number" => 36, "name" => "Himawari Kidnapped!", "airdate" => "11 Sep 2022", "runtime" => 30, "rating" => 4, "summary" => "Osuka and Himawari are kidnapped by three men. They want to extort a ransom from Osuka's mother. However, Kawaki quickly realizes that something is wrong, because Himawari did not show up for the meeting with Kae.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/579/1449494.jpg"),
        array("id" => "s2022e37", "season" => 2022, "number" => 37, "name" => "Kawaki's Cover Blown?!", "airdate" => "18 Sep 2022", "runtime" => 30, "rating" => 5.5, "summary" => "Kawaki and Himawari's class want to perform a play about the legendary Sannin at the academy festival. Eiki wants to use the chance at the rehearsals to bring Kawaki's true goal to light.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/583/1457507.jpg"),
        array("id" => "s2022e38", "season" => 2022, "number" => 38, "name" => "Target: The School Festival", "airdate" => "25 Sep 2022", "runtime" => 30, "rating" => 5, "summary" => "The school festival has begun and Himawari's class is about to perform their play. However, their performance is interrupted by a bomb threat. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/584/1460596.jpg"),
        array("id" => "s2022e39", "season" => 2022, "number" => 39, "name" => "The Sneaking Shadow", "airdate" => "2 Oct 2022", "runtime" => 30, "rating" => 4.5, "summary" => "Kae found out that Kawaki only befriended her because it was his mission to protect her. Kawaki, on the other hand, is to be pulled off the mission because he failed to report the assassin. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/584/1460737.jpg"),
        array("id" => "s2022e40", "season" => 2022, "number" => 40, "name" => "Two Sides of the Same Coin", "airdate" => "9 Oct 2022", "runtime" => 30, "rating" => 5.3, "summary" => "Life at the Academy gradually goes back to normal. Meanwhile, Hana learns about the attempt made on Kae's life and regrets her inability to prevent it. She returns to the scene of the incident to recount what occurred.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/585/1462638.jpg"),
        array("id" => "s2022e41", "season" => 2022, "number" => 41, "name" => "The Island of Treachery", "airdate" => "16 Oct 2022", "runtime" => 30, "rating" => 5.3, "summary" => "Kawaki and Himawari's class goes on a field trip to an uninhabited island. The field trip suddenly starts to feel unsettling, but the students try to work together to overcome bizarre incidents.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/585/1464421.jpg"),
        array("id" => "s2022e42", "season" => 2022, "number" => 42, "name" => "Students Unite!", "airdate" => "23 Oct 2022", "runtime" => 30, "rating" => 4, "summary" => "Kawaki and Himawari saw Hana kill Kae. However, Himawari doubts that she is really dead. With the other students, they figure out a way to track down Hana.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/428/1071549.jpg"),
        array("id" => "s2022e43", "season" => 2022, "number" => 43, "name" => "Farewell, Academy!", "airdate" => "30 Oct 2022", "runtime" => 30, "rating" => 5, "summary" => "Kae has been taken away and Kawaki and Himawari must face a dangerous assassin. They try to corner the enemy, but their opponent proves to be powerful. Will Kawaki be able to save his friends and accomplish his mission? ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/585/1464977.jpg"),
        array("id" => "s2022e44", "season" => 2022, "number" => 44, "name" => "A Flightless Hawk", "airdate" => "6 Nov 2022", "runtime" => 30, "rating" => 4.7, "summary" => "Sasuke and Boruto go on a journey to find a new falcon for Sasuke to transmit his messages to Konoha. They look for a man named Maruta, who knows a lot about long distance falcons.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/430/1076806.jpg"),
        array("id" => "s2022e45", "season" => 2022, "number" => 45, "name" => "Into the Sky Again", "airdate" => "13 Nov 2022", "runtime" => 30, "rating" => 4.7, "summary" => "Madame Mozu wants to sell Yuki. The buyer is a rich man who wants to stuff the white hawk as a taxidermy. Tsuzura wants to prevent this and runs away with Yuki. In the meantime, Boruto and Sasuke prepare everything for their trip home.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/587/1468923.jpg"),
        array("id" => "s2022e46", "season" => 2022, "number" => 46, "name" => "Welcome to the Maze", "airdate" => "20 Nov 2022", "runtime" => 30, "rating" => 4.8, "summary" => "Boruto and the others suddenly wake up in an unknown room. They are greeted by an old man who wants to do experiments with them. However, these experiments are a matter of life and death.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/604/1511492.jpg"),
        array("id" => "s2022e47", "season" => 2022, "number" => 47, "name" => "Disappearing Lives", "airdate" => "27 Nov 2022", "runtime" => 30, "rating" => 4.5, "summary" => "Boruto and the others have to endure Oga's second experiment. They are forced to carry lit candles to their destination. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/432/1080567.jpg"),
